      // Obtener la fecha actual
      var today = new Date();
      // Obtener la fecha actual menos 5 días
      var startDate = new Date();
      startDate.setDate(today.getDate() - 20);
      // Formatear el año, mes y día para la fecha de inicio
      var startYear = startDate.getFullYear();
      var startMonth = String(startDate.getMonth() + 1).padStart(2, '0'); // Meses en JavaScript son de 0 a 11
      var startDay = String(startDate.getDate()).padStart(2, '0');
      // Formatear el año, mes y día para la fecha final (hoy)
      var endYear = today.getFullYear();
      var endMonth = String(today.getMonth() + 1).padStart(2, '0');
      var endDay = String(today.getDate()).padStart(2, '0');
      // Asignar las fechas a los campos correspondientes
      this.startDate = "".concat(startYear, "-").concat(startMonth, "-").concat(startDay); // Fecha de inicio (5 días antes)
      this.endDate = "".concat(endYear, "-").concat(endMonth, "-").concat(endDay); // Fecha final (hoy)
