    operacion_Numeral_Procentaje: function operacion_Numeral_Procentaje(tipo_num_des, monto_descuento, precio_lista_gespreventa) {
      var me = this;
      var var1 = 0;
      var porcentaje = 0;
      var valorNumeral = 0;
      if (tipo_num_des === '#') {
        porcentaje = monto_descuento;
        valorNumeral = precio_lista_gespreventa - porcentaje;
        if (valorNumeral < 0) {
          valorNumeral = precio_lista_gespreventa;
          porcentaje = 0;
        }
        return {
          valorNumeral: valorNumeral,
          porcentaje: porcentaje
        };
      } else {
        if (tipo_num_des === '%') {
          porcentaje = monto_descuento / 100;
          var1 = precio_lista_gespreventa * porcentaje;
          valorNumeral = precio_lista_gespreventa - var1;
          if (valorNumeral < 0) {
            valorNumeral = precio_lista_gespreventa;
            porcentaje = 0;
          } else {
            porcentaje = var1;
          }
          return {
            valorNumeral: valorNumeral,
            porcentaje: porcentaje
          };
        }
      }
    },
    operacion_cantida_valor: function operacion_cantida_valor(tipo_can_valor, regla, cantidad_valor, precio_lista_gespreventa) {
      if (tipo_can_valor === '#') {
        if (regla === '>') {
          if (this.numero > cantidad_valor) {
            return true;
          }
        }
        if (regla === '=') {
          if (this.numero === cantidad_valor) {
            return true;
          }
        }
        if (regla === '<') {
          if (this.numero < cantidad_valor) {
            return true;
          }
        }
      }
      if (tipo_can_valor === 'BS') {
        var va = cantidad_valor.toFixed(2).toString();
        if (regla === '>') {
          if (precio_lista_gespreventa > va) {
            return true;
          }
        }
        if (regla === '=') {
          if (precio_lista_gespreventa === va) {
            return true;
          }
        }
        if (regla === '<') {
          if (precio_lista_gespreventa < va) {
            return true;
          }
        }
      }
    },
