function generateBodyTablepdfResumen(datas) {
  var body = [];

  _.forEach(datas.data, function (datageneral) {
    body.push({
      fue: {
        content: datageneral.nombre,
        styles: {
          halign: 'left'
        }
      },
      cod: datageneral.cod,
      can: datageneral.cantidad,
      mon: {
        content: datageneral.total,
        styles: {
          halign: 'right'
        }
      }
    });
  });

  body.push({
    no: {
      content: '',
      colSpan: 8,
      styles: {
        halign: 'left',
        lineWidth: 0,
        fontSize: 1,
        cellPadding: 1
      }
    }
  });
  body.push({
    fue: {
      content: 'Total general en Bolivianos',
      colSpan: 2,
      styles: {
        halign: 'right',
        fontSize: 10,
        fontStyle: 'bold',
        cellPadding: 1,
        lineWidth: 0
      }
    },
    can: {
      content: datas.cantidad,
      styles: {
        halign: 'center',
        fontStyle: 'bold'
      }
    },
    mon: {
      content: datas.monto,
      styles: {
        halign: 'right',
        fontStyle: 'bold'
      }
    }
  });
  return body;
}

